import*as THREE from'three';import{Port,materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';const tau=Math.PI*2;
/** Open helical metal runs terminate in actual material end faces. */
export function cappedThread(path,segments,radius){const radial=6,g=new THREE.TubeGeometry(path,segments,radius,radial,false),p=Array.from(g.attributes.position.array),n=Array.from(g.attributes.normal.array),uv=Array.from(g.attributes.uv.array),index=Array.from(g.index.array);for(const end of[0,1]){const center=path.getPoint(end),normal=path.getTangent(end).multiplyScalar(end?1:-1),base=p.length/3;p.push(...center.toArray());n.push(...normal.toArray());uv.push(.5,.5);for(let j=0;j<=radial;j++){const source=(end?segments*(radial+1):0)+j;p.push(...Array.from(g.attributes.position.array.slice(source*3,source*3+3)));n.push(...normal.toArray());uv.push(.5+Math.cos(j*tau/radial)*.5,.5+Math.sin(j*tau/radial)*.5);}for(let j=0;j<radial;j++)index.push(base,...(end?[base+j+2,base+j+1]:[base+j+1,base+j+2]));}g.setAttribute('position',new THREE.Float32BufferAttribute(p,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(n,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(index);return g;}
export function ring(parent,outer,inner,depth,y,m,name,hex=false){const s=new THREE.Shape();if(hex){for(let i=0;i<6;i++){const a=i*tau/6;if(i)s.lineTo(outer*Math.cos(a),outer*Math.sin(a));else s.moveTo(outer*Math.cos(a),outer*Math.sin(a));}s.closePath();}else s.absarc(0,0,outer,0,tau,false);const h=new THREE.Path();h.absarc(0,0,inner,0,tau,false);s.holes.push(h);return mesh(parent,new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:48}).rotateX(-Math.PI/2),m,[0,y,0],name);}
export function grove(host){const frame=new THREE.Group();frame.name='Cat1-CN actual blue open-top Grove UART socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const plastic=materials.plastic(spec.grove.color,{roughness:.7}),metal=materials.metal(0xb6b6a5,{roughness:.45}),box=(s,p,n,m=plastic)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'Cat1-CN Grove '+n);for(const sign of[-1,1]){box([.65,5.2,6.3],[sign*4.675,0,-3.15],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,6.3],[0,-2.275,-3.15],'floor');box([8.7,4.55,.65],[0,.325,-5.975],'deep dielectric rear wall');box([4.8,.45,2.3],[0,2.375,-4.5],'locking bridge');const contacts=[],tails=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],'actual contact '+(i+1),metal));const tail=new THREE.Group();tail.name='Cat1-CN Grove actual right-angle solder tail '+(i+1);frame.add(tail);mesh(tail,new THREE.BoxGeometry(.42,.42,2.0),metal,[(i-1.5)*2,.2,-6.7],'Cat1-CN Grove rearward solder leg');mesh(tail,new THREE.BoxGeometry(.42,.9,.42),metal,[(i-1.5)*2,.65,-7.7],'Cat1-CN Grove actual plated-through solder tail');tails.push(tail);}const port=host.add(new Port({id:'grove',label:'PORT.C · UART appearance',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'RXD',color:'yellow'},{n:4,name:'TXD',color:'white'}],pinGrid:{cols:4,rows:1,pitch:2,center:[0,.2],order:col=>4-col},meta:{role:'visual-connector',face:'bottom',scope:'Four real contact labels,physical attachment and cable pose only.No UART,AT,power,network,SIM,RF,electrical or firmware behavior'}}));return{frame,contacts,tails,port};}
export function sma(host){const frame=new THREE.Group();frame.name='Cat1-CN actual ordinary SMA female coax bulkhead';frame.position.fromArray(spec.sma.position);host.body.add(frame);const gold=materials.metal(0xc6b76e,{roughness:.4}),ptfe=materials.plastic(0xe5e4d0,{roughness:.78}),dark=materials.plastic(0x20261f,{roughness:.88}),shell=ring(frame,3.175,2.65,6,-6,gold,'Cat1-CN SMA female open threaded shell'),dielectric=ring(frame,2.65,.45,1.4,-1.6,ptfe,'Cat1-CN SMA female physical dielectric and center bore'),contact=ring(frame,.43,.28,4,-5.6,gold,'Cat1-CN SMA actual hollow female center contact'),blind=mesh(frame,new THREE.CylinderGeometry(.43,.43,.12,32),gold,[0,-5.66,0],'Cat1-CN SMA actual center contact blind end'),shaft=ring(frame,3.1,1.2,7,-13,gold,'Cat1-CN SMA bulkhead barrel'),internalHex=ring(frame,4.6188,1.2,2.5,-13.3,gold,'Cat1-CN real gold internal SMA hex body behind paired native windows',true),externalHex=ring(frame,4.6188,3.18,1.6,-7.4,gold,'Cat1-CN actual external SMA hex mounting nut',true),washer=ring(frame,4.0,3.15,.35,-7.75,gold,'Cat1-CN SMA mounting washer'),crimp=ring(frame,1.8,.55,1.8,-15.1,gold,'Cat1-CN actual coax termination crimp'),sleeve=ring(frame,1.05,.48,1.5,-16,dark,'Cat1-CN fixed black coax heatshrink');class Thread extends THREE.Curve{getPoint(t,v=new THREE.Vector3()){const a=t*tau*7;return v.set(Math.cos(a)*3.17,-5.3+t*5.0,Math.sin(a)*3.17);}}const thread=mesh(frame,cappedThread(new Thread(),448,.065),gold,[0,0,0],'Cat1-CN real SMA external helical thread');const port=host.add(new Port({id:'sma',label:'Ordinary SMA female · external antenna',connector:'sma-female',position:spec.sma.position,hitSize:[7,1,7],pins:[{name:'center ANT female contact'},{name:'outer shield'}],meta:{role:'visual-connector',face:'top',physicalConnector:'sma-female',source:'Own U204_06/12 show outer threads and hollow center;own bare-board05 shows IPEX/coax/bulkhead',scope:'Ordinary SMA physical attachment only,not RP-SMA.No radio,RF,cellular/network,electrical or antenna-performance behavior'}}));return{frame,shell,dielectric,contact,blind,shaft,internalHex,externalHex,washer,crimp,sleeve,thread,port};}
